    Args:
        a (int): The number to check.

    Returns:
        bool: True if the number is the product of exactly three prime numbers, False otherwise.
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Check if the number has exactly three prime factors (counted with multiplicity)
    # We'll factorize the number and count the number of prime factors
    def count_prime_factors(n):
        count = 0
